insert into public.content_item_versions(item_id,version,body,normalized_body,metadata,editorial_status,change_note) values
  ('1d3b2e74-8acf-56d0-a5f6-ff4784715c9c'::uuid,1,'Where do you want us to use more precise language instead of broad labels?','where do you want us to use more precise language instead of broad labels','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('9a2d5739-b908-5e1d-aa51-b175b44acf8a'::uuid,1,'How can we respond to hurt without turning intent into a shield?','how can we respond to hurt without turning intent into a shield','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('c4c88328-3e91-5902-b54f-ad653d790d57'::uuid,1,'What aspect of your self-understanding is currently in motion?','what aspect of your self understanding is currently in motion','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('0a918e04-0166-5eec-8bfe-452ae4f76563'::uuid,1,'Which shared expectation would you like to turn into a clear invitation?','which shared expectation would you like to turn into a clear invitation','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('9cba3ecc-1c53-58ba-ae59-c039861ebd81'::uuid,1,'What helps you reconnect after you have felt emotionally crowded?','what helps you reconnect after you have felt emotionally crowded','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('4196fec6-dfcd-5e4b-8fa2-fd7ab6ed701f'::uuid,1,'Where could we practice asking before offering comfort or touch?','where could we practice asking before offering comfort or touch','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('34fd1591-8f14-5678-80d6-660f07b27b24'::uuid,1,'How do you want us to divide responsibility for initiating important talks?','how do you want us to divide responsibility for initiating important talks','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('5891c87f-156e-5f69-9c68-80a9e983132a'::uuid,1,'What part of our connection do you want to protect from constant optimization?','what part of our connection do you want to protect from constant optimization','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('d978f5c2-fd4b-5bdd-a509-f79909c9f4df'::uuid,1,'Which future plan needs more curiosity about its day-to-day reality?','which future plan needs more curiosity about its day to day reality','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('0afed56a-7477-536e-bc36-ed08bb7ece3d'::uuid,1,'What would help you trust that disagreement will not erase affection?','what would help you trust that disagreement will not erase affection','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('d71a6a14-50d7-552d-b7aa-d06264efb873'::uuid,1,'Where might a request for reassurance be asking for something more specific?','where might a request for reassurance be asking for something more specific','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('b276195c-c5a3-5f4d-80f4-b0e112e6ca9b'::uuid,1,'How has your view of loyalty become more nuanced over time?','how has your view of loyalty become more nuanced over time','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('05ce6cc4-fde9-57ad-be11-9d989b2d1b48'::uuid,1,'What need for recognition would you like to name without keeping score?','what need for recognition would you like to name without keeping score','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('027a3bd8-287c-5458-8f9e-d1116280d49d'::uuid,1,'Which area of shared life could benefit from a trial period rather than a permanent decision?','which area of shared life could benefit from a trial period rather than a permanent decision','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('920b66e8-9241-590a-85dd-7cfc95d7f240'::uuid,1,'What does it mean to be emotionally honest while keeping some thoughts private?','what does it mean to be emotionally honest while keeping some thoughts private','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('cc1ce68a-7cd6-551c-b2f8-9374eff03dd9'::uuid,1,'Where do you want to feel more consulted before plans take shape?','where do you want to feel more consulted before plans take shape','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('7a37805e-08d6-51bd-aba2-73de1e19feb4'::uuid,1,'How can we tell when compromise has started to feel like self-abandonment?','how can we tell when compromise has started to feel like self abandonment','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('c0d3b840-db21-53d2-a131-a50a4d2e98ac'::uuid,1,'What part of our connection deserves rest rather than more effort?','what part of our connection deserves rest rather than more effort','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('1ef97ed7-f415-5325-a367-e7ca7446743f'::uuid,1,'Which experience changed what you require to feel respected?','which experience changed what you require to feel respected','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('29a0ac17-cc8e-576b-a79a-8658aa5b3d59'::uuid,1,'What would make a boundary conversation feel like coordination, not rejection?','what would make a boundary conversation feel like coordination not rejection','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('a34e4803-c7c6-58f3-8b0e-2635b41a8ee9'::uuid,1,'Where could we better acknowledge that both perspectives may be incomplete?','where could we better acknowledge that both perspectives may be incomplete','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('2fd97ec2-685d-5d5f-8836-1f56091fe359'::uuid,1,'How do you want us to handle outside pressures that shape our choices?','how do you want us to handle outside pressures that shape our choices','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('d14f69f1-4743-5056-9b1e-89c7f0b5b4c3'::uuid,1,'What emerging part of your identity needs room without needing explanation?','what emerging part of your identity needs room without needing explanation','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('f2fcd908-ddbe-5b07-ac7e-c011b89de0b1'::uuid,1,'Which repair attempt from me is easiest for you to receive?','which repair attempt from me is easiest for you to receive','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('29a1a477-bab2-51a7-9d4d-564094c1a186'::uuid,1,'What helps you notice when you are agreeing mainly to preserve harmony?','what helps you notice when you are agreeing mainly to preserve harmony','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('f646910a-c6a3-58a0-bf64-04ff1597ecba'::uuid,1,'Where might our ideas of fairness be using different measures?','where might our ideas of fairness be using different measures','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('ad0868ff-d21a-5680-8f18-9f3186d4d784'::uuid,1,'How can we stay kind when clarity arrives at different times for each of us?','how can we stay kind when clarity arrives at different times for each of us','{}'::jsonb,'published','Initial deterministic bundled-content import'),
