insert into public.content_item_versions(item_id,version,body,normalized_body,metadata,editorial_status,change_note) values
  ('827bd063-b785-525a-8805-7b7bfb76a88d'::uuid,1,'They value punctuality and become anxious when you run late.','they value punctuality and become anxious when you run late','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('1f674d6f-1639-506f-854d-4b53c8e4db86'::uuid,1,'They take work calls during holidays but keep them brief.','they take work calls during holidays but keep them brief','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('e93d63c3-0ca2-5893-9a8c-683838438b04'::uuid,1,'They love hosting overnight guests in shared space.','they love hosting overnight guests in shared space','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('97815a76-2776-5321-ba1a-ec8ab7c77dfb'::uuid,1,'They spend free weekends completing household projects.','they spend free weekends completing household projects','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('c173277f-829c-5ae6-ae97-c80231d3e920'::uuid,1,'They prefer routine meals and rarely try unfamiliar food.','they prefer routine meals and rarely try unfamiliar food','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('8d82d62f-ffec-5a35-a421-8eeea04536fd'::uuid,1,'They meditate every morning and do not want interruptions.','they meditate every morning and do not want interruptions','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('67c1402d-1b9d-5d09-8cc3-2b7d9e6faecf'::uuid,1,'They attend religious services and do not expect you to join.','they attend religious services and do not expect you to join','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('b0945fab-827d-5bf5-aae4-fbfd7db65886'::uuid,1,'They want a television in the bedroom.','they want a television in the bedroom','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('ebb71c8c-f5f2-5579-8e3e-bb330da92888'::uuid,1,'They want to hire someone for every chore you both dislike, including folding laundry.','they want to hire someone for every chore you both dislike including folding laundry','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('ce41c80e-2ad6-5407-b00a-bd67c3042a26'::uuid,1,'They need the room cold to sleep comfortably.','they need the room cold to sleep comfortably','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('82808e86-55b4-5913-9de8-f33744f1c18f'::uuid,1,'They collect items that occupy significant space.','they collect items that occupy significant space','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('bdde10be-ccc8-511b-ae1f-2e4d339e0b14'::uuid,1,'They begin every new health kick on Monday and recruit you before buying the groceries.','they begin every new health kick on monday and recruit you before buying the groceries','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('6601bdb6-2d6e-5a7f-88d5-9eee9b83fc4c'::uuid,1,'They enjoy spontaneous visitors while you prefer planned company.','they enjoy spontaneous visitors while you prefer planned company','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('0cd2de66-7580-5dc3-89aa-c6ee9ba3ef58'::uuid,1,'They require complete silence while concentrating.','they require complete silence while concentrating','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('0556607a-04a1-594a-9f1b-d4768e4adadd'::uuid,1,'They spend several hours each week gaming with friends.','they spend several hours each week gaming with friends','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('2ede518c-75a8-53e2-a079-28b404736d2e'::uuid,1,'They never drink, but become the most enthusiastic person at karaoke night.','they never drink but become the most enthusiastic person at karaoke night','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('4af832ec-de1b-5a36-a4c0-1a748347f9eb'::uuid,1,'They want to live in the countryside while your career is city-based.','they want to live in the countryside while your career is city based','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('923f3021-cf14-5571-8be9-7a4bf09e0ff4'::uuid,1,'They clean when stressed and expect nobody to interfere.','they clean when stressed and expect nobody to interfere','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('555a0394-b045-589d-94f1-4f5cc3c5902f'::uuid,1,'They protect sleep even when it means leaving events early.','they protect sleep even when it means leaving events early','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('384c02a7-b7f4-5760-8b6e-d2092a0a0bab'::uuid,1,'They discuss marriage early because they date with that intention.','they discuss marriage early because they date with that intention','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('c62bdb51-7342-575b-b56f-3b9543d357fb'::uuid,1,'They definitely want children “someday” but refuse to discuss what someday means.','they definitely want children someday but refuse to discuss what someday means','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('6ac4c598-50e5-5a77-b154-4d918adfcf64'::uuid,1,'They avoid labels while behaving like a committed partner.','they avoid labels while behaving like a committed partner','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('f671d0b6-bcd1-59ed-8d21-e58935a5db30'::uuid,1,'They include you in long-term plans after only a few dates.','they include you in long term plans after only a few dates','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('b26d9f57-9c5c-5a75-9527-a02fe776c6d8'::uuid,1,'They want to live together before considering engagement.','they want to live together before considering engagement','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('340c2582-e343-5b5b-8247-2f0e1dd31f64'::uuid,1,'They prefer a long engagement with no urgent wedding plans.','they prefer a long engagement with no urgent wedding plans','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('6f50469d-e1ca-53bc-b915-67752d448e41'::uuid,1,'They happily plan next weekend but treat any conversation about five years from now like a trap.','they happily plan next weekend but treat any conversation about five years from now like a trap','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('68e480d8-fafc-5344-854a-323992e18768'::uuid,1,'They want to keep their surname after marriage.','they want to keep their surname after marriage','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('ae8a5bd4-8d24-5c31-b263-b44fc6100b16'::uuid,1,'They imagine relocating abroad within five years.','they imagine relocating abroad within five years','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('7704b450-ae7f-5269-b00c-d709b02d1c7a'::uuid,1,'They want legal agreements protecting both partners before marriage.','they want legal agreements protecting both partners before marriage','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('d7362ff7-1789-5709-a949-42dc77d77c1c'::uuid,1,'Before deciding about children, they propose interviewing every parent you know.','before deciding about children they propose interviewing every parent you know','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('ae6ef14a-3286-5c28-8d5b-60a860c831f6'::uuid,1,'They believe commitment matters more than formal marriage.','they believe commitment matters more than formal marriage','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('6505961f-21eb-58c5-b18d-87a3ab51f862'::uuid,1,'They want to buy property together before getting engaged.','they want to buy property together before getting engaged','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('4b7accc1-00b7-5dd2-b525-5ca3e3465f14'::uuid,1,'They set relationship goals and review them every year.','they set relationship goals and review them every year','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('e2d12b03-011c-520c-9123-61de1f3328f8'::uuid,1,'They hesitate to promise forever but consistently show up now.','they hesitate to promise forever but consistently show up now','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('9071197b-9c41-59fe-8a95-6e7fd2e234be'::uuid,1,'They want future caregiving responsibilities discussed in advance.','they want future caregiving responsibilities discussed in advance','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('6d28e944-bb70-527a-9b60-a903abba5bb6'::uuid,1,'They expect both partners to remain financially independent.','they expect both partners to remain financially independent','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('1912cab6-3079-5476-9ac6-e0a83942ce28'::uuid,1,'They want a very small wedding despite having a large family.','they want a very small wedding despite having a large family','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('f936f1b3-c689-50b9-ab26-d46bc1185758'::uuid,1,'They preserve personal goals that might require time apart.','they preserve personal goals that might require time apart','{}'::jsonb,'published','Initial deterministic bundled-content import'),
