insert into public.content_item_versions(item_id,version,body,normalized_body,metadata,editorial_status,change_note) values
  ('3556e430-e582-55df-b727-604e10396bff'::uuid,1,'Tap a five-beat pattern and invite the room to echo it once. Or drink.','tap a five beat pattern and invite the room to echo it once or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('05c4f0e6-013b-5df7-8280-58f34b21eada'::uuid,1,'Make a rhythm inspired by a ticking clock that speeds up slightly. Or drink.','make a rhythm inspired by a ticking clock that speeds up slightly or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('3c7e0f27-630a-5976-b70d-7b0987700953'::uuid,1,'Alternate a clap and a knee tap twelve times without breaking tempo. Or drink.','alternate a clap and a knee tap twelve times without breaking tempo or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('1ff32977-3612-5eea-9789-cc6fc6cea0ad'::uuid,1,'Create a quiet rhythm using only fingertip taps. Or drink.','create a quiet rhythm using only fingertip taps or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('02ebe1b8-1bbc-5a1d-9c47-f313874dc99a'::uuid,1,'Beatbox a simple pattern for ten seconds at an even pace. Or drink.','beatbox a simple pattern for ten seconds at an even pace or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('bc4be649-8a1b-5348-b925-e86ef4fab6c8'::uuid,1,'Conduct an imaginary orchestra through four slow beats and four fast beats. Or drink.','conduct an imaginary orchestra through four slow beats and four fast beats or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('ea1e6f37-2b18-5b06-8e1d-3e93fec2adc6'::uuid,1,'Say one, two, three, four while clapping only on two and four. Or drink.','say one two three four while clapping only on two and four or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('90098d89-a935-582a-afd7-0499775b3d7e'::uuid,1,'Invent a three-sound rhythm and perform it backward. Or drink.','invent a three sound rhythm and perform it backward or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('34ffaa89-4d42-5c26-bb9b-acc883bafc08'::uuid,1,'Keep time with one hand while the other marks every third beat. Or drink.','keep time with one hand while the other marks every third beat or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('6fc78722-b54e-55a7-860e-e1f942de08a4'::uuid,1,'Name five rectangular things you can see from your seat. Or drink.','name five rectangular things you can see from your seat or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('d0b5c881-b527-52a9-bc94-bba30daec464'::uuid,1,'Find two objects in the room that share an unexpected color. Or drink.','find two objects in the room that share an unexpected color or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('7e707271-1447-568a-8917-3b773c6c0cd5'::uuid,1,'Identify the nearest object with visible writing and count its words. Or drink.','identify the nearest object with visible writing and count its words or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('f356d48b-ebe3-5c0a-8c5f-c71ac7302439'::uuid,1,'Spot something in the room that has both a curved edge and a straight edge. Or drink.','spot something in the room that has both a curved edge and a straight edge or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('f7fde06c-ad20-570f-a0dd-c53efbebd1ad'::uuid,1,'Name three different materials visible in the room. Or drink.','name three different materials visible in the room or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('bd60157c-15ae-5807-a9e7-77ba0b7ced70'::uuid,1,'Find an object whose shadow resembles a different object. Or drink.','find an object whose shadow resembles a different object or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('3f9e6950-dcb6-551c-a894-632f68e4b02e'::uuid,1,'Identify the smallest clearly visible item without leaving your seat. Or drink.','identify the smallest clearly visible item without leaving your seat or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('dc5cfb25-ce46-532e-b860-9b97af43ba83'::uuid,1,'Name two objects positioned at roughly the same height. Or drink.','name two objects positioned at roughly the same height or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('12eab0b9-7939-5513-b846-888be761cc22'::uuid,1,'Find a repeating pattern somewhere in the room and describe it. Or drink.','find a repeating pattern somewhere in the room and describe it or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('33a8f35f-c221-58be-b738-ece72b813eaa'::uuid,1,'Point out an object that could be viewed as perfectly symmetrical. Or drink.','point out an object that could be viewed as perfectly symmetrical or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
