  ('5dc1d976-ff32-533d-8239-f647655ad68a'::uuid,1,'Identify one item that reflects light and one that absorbs it. Or drink.','identify one item that reflects light and one that absorbs it or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('a726d588-9948-548e-86ce-23b53c5914a8'::uuid,1,'Name three visible objects arranged from nearest to farthest. Or drink.','name three visible objects arranged from nearest to farthest or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
