insert into public.content_item_versions(item_id,version,body,normalized_body,metadata,editorial_status,change_note) values
  ('fa1dbc64-fc33-548f-a527-2f7e7a5d5304'::uuid,1,'Was this theft, favouritism or a costly misunderstanding?','was this theft favouritism or a costly misunderstanding','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('0530625f-df37-5205-934b-307ab1e3f24e'::uuid,1,'Defend the two unrelated names on the delivery list.','defend the two unrelated names on the delivery list','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('553eca0f-41d6-5191-a679-96c24ea46db8'::uuid,1,'Decide whether unclear permission can excuse what happened.','decide whether unclear permission can excuse what happened','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('8749ecc8-6ed0-56de-a8df-fd8356f22ebb'::uuid,1,'The groom-to-be’s ex arrived with a printed invitation bearing the correct family colour code and private address.','the groom to be''s ex arrived with a printed invitation bearing the correct family colour code and private address','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('e1918953-23dc-5aaf-995c-55fb3ec7eeab'::uuid,1,'Only five people had the final guest list, and the unexpected guest knew exactly when gifts would be presented.','only five people had the final guest list and the unexpected guest knew exactly when gifts would be presented','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('9de7cd4f-7646-59ce-b65f-a533af15fdfd'::uuid,1,'You invited the ex under a false name to embarrass the couple and force a private secret into the open.','you invited the ex under a false name to embarrass the couple and force a private secret into the open','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('650bb842-d2b3-5f36-93b2-ca016046e5f3'::uuid,1,'You sent an early invitation design to the ex months earlier while asking for printing advice. You never invited them, but later forwarded the final event schedule to a planning assistant without noticing the old email chain was attached.','you sent an early invitation design to the ex months earlier while asking for printing advice you never invited them but later forwarded the final event schedule to a planning assistant without noticing the old email chain was attached','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('bd1c3970-1f58-59ba-b5f1-463a0a751238'::uuid,1,'The false guest name is the same nickname the Accused used for the ex in an old contact list.','the false guest name is the same nickname the accused used for the ex in an old contact list','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('458e1569-b14d-5477-b6e1-fe3d9f7f2202'::uuid,1,'The invitation PDF was exported from the Accused’s laptop, but the export date predates the final venue booking.','the invitation pdf was exported from the accused''s laptop but the export date predates the final venue booking','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('83b7e710-b5e6-5927-bd71-1e980e5cb322'::uuid,1,'The planning assistant forwarded the schedule to a printer whose address auto-completed to the ex’s similarly named email account.','the planning assistant forwarded the schedule to a printer whose address auto completed to the ex''s similarly named email account','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('60542711-f557-5bfb-a618-76a4166aa84c'::uuid,1,'The ex admits receiving the schedule by mistake, but claims the Accused’s earlier message—“If you knew the full story, you would show up yourself”—felt like permission to attend.','the ex admits receiving the schedule by mistake but claims the accused''s earlier message if you knew the full story you would show up yourself felt like permission to attend','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('4d1b5f30-9319-5f13-a43a-20a1aed5cc28'::uuid,1,'Explain the threatening message without admitting an invitation.','explain the threatening message without admitting an invitation','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('52c34df9-6f34-5e5c-854a-d85bd74bc031'::uuid,1,'Who had enough information to complete the old PDF?','who had enough information to complete the old pdf','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('d9b9a6a8-78f5-5286-9000-ea578a2519eb'::uuid,1,'Argue whether reckless gossip makes the Accused responsible for the disruption.','argue whether reckless gossip makes the accused responsible for the disruption','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('7d914430-9be9-5330-af09-048c7b9f12aa'::uuid,1,'The group agreed to split one table package. At closing time, four premium bottles and a stranger’s food order appeared on the bill.','the group agreed to split one table package at closing time four premium bottles and a stranger''s food order appeared on the bill','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('d541386e-b298-591c-8e75-6b96569efbc1'::uuid,1,'The club insists every addition was confirmed with the table’s private four-digit code.','the club insists every addition was confirmed with the table''s private four digit code','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('5bf1f319-7269-5580-9328-6604d6590b9b'::uuid,1,'You shared the table code with another group, enjoyed their attention and left your friends to pay for it.','you shared the table code with another group enjoyed their attention and left your friends to pay for it','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('899aa4a4-dc38-545a-a89a-da616be53615'::uuid,1,'You gave the code to one person only after they promised to replace a bottle they accidentally knocked over. You did not approve the other orders.','you gave the code to one person only after they promised to replace a bottle they accidentally knocked over you did not approve the other orders','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('8994ae3b-2dda-5825-a5de-3164060df742'::uuid,1,'A video shows the Accused celebrating when the extra bottles arrived and shouting, “Put everything on us!”','a video shows the accused celebrating when the extra bottles arrived and shouting put everything on us','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('be2e80b2-bc3e-591a-b29c-6525f0bc0f2f'::uuid,1,'The waiter’s device records three approvals, all using the correct code but entered by two different staff members.','the waiter''s device records three approvals all using the correct code but entered by two different staff members','{}'::jsonb,'published','Initial deterministic bundled-content import'),
